const _kLocaleStorageKey = '__locale_key__';

/// A selectable app language with display metadata for language pickers.
class AppLanguage {
  const AppLanguage(this.code, this.flag, this.nativeName);

  final String code;
  final String flag;
  final String nativeName;
}

/// Single source of truth for supported in-app languages (with picker metadata).
/// Add a language here to surface it in the locale list and every language picker.
/// Keep in sync with iOS CFBundleLocalizations and the backend language maps.
const List<AppLanguage> kAppLanguages = [
  AppLanguage('en', '🇺🇸', 'English'),
  AppLanguage('ru', '🇷🇺', 'Русский'),
  AppLanguage('es', '🇪🇸', 'Español'),
  AppLanguage('de', '🇩🇪', 'Deutsch'),
  AppLanguage('fr', '🇫🇷', 'Français'),
  AppLanguage('it', '🇮🇹', 'Italiano'),
  AppLanguage('pt', '🇧🇷', 'Português'),
  AppLanguage('tr', '🇹🇷', 'Türkçe'),
  AppLanguage('ja', '🇯🇵', '日本語'),
  AppLanguage('ko', '🇰🇷', '한국어'),
  AppLanguage('zh', '🇨🇳', '简体中文'),
];

/// Language codes derived from [kAppLanguages], used for locale resolution.
final List<String> kSupportedLanguages =
    kAppLanguages.map((l) => l.code).toList(growable: false);

class FFLocalizations {
  FFLocalizations(this.locale);

  final Locale locale;

  static FFLocalizations of(BuildContext context) =>
      Localizations.of<FFLocalizations>(context, FFLocalizations)!;

  static List<String> languages() => kSupportedLanguages;

  static late SharedPreferences _prefs;
  static Future initialize() async =>
      _prefs = await SharedPreferences.getInstance();
  static Future storeLocale(String locale) =>
      _prefs.setString(_kLocaleStorageKey, locale);
  static Locale? getStoredLocale() {
    final locale = _prefs.getString(_kLocaleStorageKey);
    return locale != null && locale.isNotEmpty ? createLocale(locale) : null;
  }

  String get languageCode => locale.toString();
  String? get languageShortCode =>
      _languagesWithShortCode.contains(locale.toString())
          ? '${locale.toString()}_short'
          : null;
  String getText(String key) {
    final translations = kTranslationsMap[key] ?? const {};
    final value = translations[locale.toString()];
    if (value != null && value.isNotEmpty) {
      return value;
    }
    // Fall back to English for not-yet-translated keys so newly added
    // locales never render blank strings.
    return translations['en'] ?? '';
  }

  static const Set<String> _languagesWithShortCode = {
    'ar',
    'az',
    'ca',
    'cs',
    'da',
    'de',
    'dv',
    'en',
    'es',
    'et',
    'fi',
    'fr',
    'gr',
    'he',
    'hi',
    'hu',
    'it',
    'km',
    'ku',
    'mn',
    'ms',
    'no',
    'pt',
    'ro',
    'ru',
    'rw',
    'sv',
    'th',
    'uk',
    'vi',
  };
}

/// Used if the locale is not supported by GlobalMaterialLocalizations.
class FallbackMaterialLocalizationDelegate
    extends LocalizationsDelegate<MaterialLocalizations> {
  const FallbackMaterialLocalizationDelegate();

  @override
  bool isSupported(Locale locale) => _isSupportedLocale(locale);

  @override
  Future<MaterialLocalizations> load(Locale locale) async =>
      SynchronousFuture<MaterialLocalizations>(
        const DefaultMaterialLocalizations(),
      );

  @override
  bool shouldReload(FallbackMaterialLocalizationDelegate old) => false;
}

/// Used if the locale is not supported by GlobalCupertinoLocalizations.
class FallbackCupertinoLocalizationDelegate
    extends LocalizationsDelegate<CupertinoLocalizations> {
  const FallbackCupertinoLocalizationDelegate();

  @override
  bool isSupported(Locale locale) => _isSupportedLocale(locale);

  @override
  Future<CupertinoLocalizations> load(Locale locale) =>
      SynchronousFuture<CupertinoLocalizations>(
        const DefaultCupertinoLocalizations(),
      );

  @override
  bool shouldReload(FallbackCupertinoLocalizationDelegate old) => false;
}

class FFLocalizationsDelegate extends LocalizationsDelegate<FFLocalizations> {
  const FFLocalizationsDelegate();

  @override
  bool isSupported(Locale locale) => _isSupportedLocale(locale);

  @override
  Future<FFLocalizations> load(Locale locale) =>
      SynchronousFuture<FFLocalizations>(FFLocalizations(locale));

  @override
  bool shouldReload(FFLocalizationsDelegate old) => false;
}

Locale createLocale(String language) => language.contains('_')
    ? Locale.fromSubtags(
        languageCode: language.split('_').first,
        scriptCode: language.split('_').last,
      )
    : Locale(language);

bool _isSupportedLocale(Locale locale) {
  final language = locale.toString();
  return FFLocalizations.languages().contains(
    language.endsWith('_')
        ? language.substring(0, language.length - 1)
        : language,
  );
}

